module Bi_Dir_Shift_Reg_beh (output reg [1: 4] D_out, input [1: 4] D_in, input SEL, STB, SH_LD, clock, CLR_bar);  always @ (posedge clock, negedge CLR_bar)    if (!CLR_bar) D_out <= 4'b0;    else if (SH_LD ) D_out <= {D_out[4], D_out[1], D_out[2], D_out[3]};   else if (!STB) D_out <= SEL ? {D_out[2: 4], D_out[1]}: D_in;    else D_out <= 4'b0; endmodulemodule t_Bi_Dir_Shift_Reg_beh ();  wire [1: 4] D_out;  reg [1: 4] D_in;  reg SEL, STB, SH_LD, clock, CLR_bar;  Bi_Dir_Shift_Reg_beh M0 (D_out, D_in, SEL, STB, SH_LD, clock, CLR_bar);  initial #200 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    D_in = 4'h8;		// Data for walking 1 to right    CLR_bar = 0;    STB = 0;    SEL = 0;		// Selects D_in    SH_LD = 0;		// load D_in    #10 CLR_bar = 1;     #20 STB = 1;    #40 STB = 0;    #30 SH_LD = 1;	     #50 SH_LD = 0;	// Interrupt count to load    #60 SH_LD = 1;    #80 SEL = 1;    #100 STB = 1;    #130 STB = 0;    #140 SH_LD = 0;    //#150 SH_LD = 1;  joinendmodule